    english_customer_response_template: 'Hi {{USERNAME}}, the attachment you opened was malicious. Our endpoint tools blocked the attack, and we isolated your computer briefly to clean it and run a full scan. Please do not open unexpected attachments, even from known contacts, and enable the macro warning is never safe to dismiss. We removed the email from all mailboxes. Your account was not compromised, but contact us immediately if anything looks unusual.',
