    escalation: 'Si la regla reenvía a una dirección externa y hay instrucciones de pago ocultas, es P1: IR lead, Finanzas y legal de inmediato. Si la técnica aparece en varios buzones, declare incidente mayor (campaña de BEC) y siga RB-SOC-031.',
    english_customer_response_template: 'Hi {{USERNAME}}, we found that an attacker created a hidden rule in your mailbox that was deleting or moving messages related to payments, so you would not see them. We removed the rule, reset your password, and signed out the attacker. Please check your deleted and archive folders for missing messages and tell us about any payment instructions you did not send. We will keep monitoring your mailbox for new rules.',
    english_technical_explanation: 'Attacker-created inbox rule on the {{USERNAME}} mailbox (T1098 account manipulation) detected via Search-UnifiedAuditLog (New-InboxRule from {{SOURCE_IP}}) and Get-InboxRule showing a rule forwarding and deleting payment-related messages. Containment: rule removed with Remove-InboxRule, sessions revoked and password reset; mailbox permissions and forwarding verified clean. Verification: no new rules in unified audit for 24 hours and test message delivered to inbox. Finance confirmed no payments were instructed by the attacker.',
    keywords: ['regla de bandeja', 'inbox rule', 'new-inboxrule', 'ocultar correos', 'bec', 'fraude', 'redirect', 'forwardto', 'redirectto', 'deletemessage', 'movetofolder', 'auditoria unificada', 'unified audit log', 'get-inboxrule', 'remove-inboxrule', 'delegacion', 'mailbox permission'],
