    english_customer_response_template: 'Hi {{USERNAME}}, we detected password-cracking tooling running from your computer that targets our service accounts. We isolated the machine and rotated the exposed service account passwords, so the attacker cannot use them. We are investigating how the tooling reached your computer. Please avoid installing or running unknown admin tools, and tell us right away if anything prompted you to run a program.',
    english_technical_explanation: 'Kerberoasting indicators on {{HOSTNAME}} at {{TIMESTAMP}}: Rubeus-style process command lines in DeviceProcessEvents requesting service tickets (T1003 credential dumping). Investigation: service accounts with SPNs inventoried with Get-ADUser, several with passwords unchanged for years; 4771 events reviewed for Kerberos context. Containment: host isolated and executing account disabled. Remediation: service account passwords rotated with Set-ADAccountPassword, prioritized by age and privilege; gMSA migration planned. Verification: no new tool executions and no anomalous service-account logons after rotation.',
