    english_customer_response_template: 'Hi {{USERNAME}}, our monitoring detected a suspicious program chain running on your computer, likely triggered by a document or link. We blocked the process, cleaned the machine, and ran a full scan with no threats remaining. Your account was not compromised. Please avoid opening documents that ask to enable macros, and tell us if you opened anything unusual before the alert.',
    english_technical_explanation: 'Suspicious process lineage (T1059.001) on {{HOSTNAME}} at {{TIMESTAMP}}: SecurityEvent 4688 showed Office/browser parents spawning command interpreters with encoded command lines; full lineage reconstructed with DeviceProcessEvents (three generations) and base64 payload decoded to a downloader URL. Containment: host isolated after confirming outbound traffic from the process; hashes and URL blocked as indicators. Remediation: Remove-MpThreat plus full scan, persistence checks (scheduled tasks, run keys, WMI) negative. Verification: no new anomalous lineages in 24 hours.',
