    business_impact: 'El borrado destruye la evidencia de la actividad del atacante en el host justo en la ventana crítica del incidente, impidiendo dimensionar el alcance y demostrar exfiltración; en un DC, el 1102 puede estar enmascarando manipulación del dominio en curso.',
