    english_customer_response_template: 'Hi {{USERNAME}}, we detected an obfuscated command and a Windows utility being misused on your computer to download malicious content. We blocked the download, cleaned the machine, and a full scan shows no threats. Your account was not compromised. Please tell us what you opened or downloaded before the alert; that helps us block the source for everyone.',
    english_technical_explanation: 'Suspicious execution (T1059.001) on {{HOSTNAME}} at {{TIMESTAMP}}: encoded PowerShell command line plus LOLBin usage (certutil with URL) detected via DeviceProcessEvents; base64 decoded revealing the payload URL. Investigation: lineage shows Office as parent (macro-dropped downloader). Containment: URL and hash blocked, host isolated, payload removed with Get-MpThreat/Remove-MpThreat, full scan clean. Verification: no new encoded executions or LOLBin downloads in 24 hours; fleet sweep by hash negative.',
