      'DeviceProcessEvents | where TimeGenerated > ago(24h) | where ProcessCommandLine has_any ("mofcomp", "wmic") | project Timestamp, DeviceName, FileName, ProcessCommandLine, AccountName | order by Timestamp desc',
      'DeviceProcessEvents | where DeviceName == "{{HOSTNAME}}" | where InitiatingProcessFileName =~ "WmiPrvSE.exe" | project Timestamp, FileName, ProcessCommandLine | order by Timestamp desc',
