    escalation: 'Suscripción activa con payload malicioso o que reaparece tras la remoción es P1: IR lead y aislamiento total del host. Suscripciones en varios hosts decretan incidente mayor (campaña de implantes); el hallazgo alimenta detecciones de WMI (RB-SOC-027).',
    english_customer_response_template: 'Hi {{USERNAME}}, we found a hidden persistence mechanism on your computer that used Windows management subscriptions to relaunch malware whenever certain system events happened. We removed the subscription, the malicious program it launched, and completed a full scan with no threats left. Your account was not compromised. Please let us know if anything prompted you to run a program before the alert.',
    english_technical_explanation: 'WMI event subscription persistence on {{HOSTNAME}} at {{TIMESTAMP}}: __EventFilter (60-second interval), __CommandLineEventConsumer (payload in AppData) and __FilterToConsumerBinding enumerated with Get-CimInstance in root\\subscription; installation traced to mofcomp in DeviceProcessEvents; payload executions confirmed under WmiPrvSE.exe. Containment: host isolated. Remediation: binding, consumer and filter removed with Remove-CimInstance, payload quarantined, full scan clean. Verification: only legitimate subscription objects remain and no WmiPrvSE.exe child executions in 24 hours.',
    keywords: ['wmi', 'suscripcion wmi', 'wmi subscription', 'eventfilter', 'commandlineeventconsumer', 'filtertoconsumerbinding', 'root\\subscription', 'mofcomp', 'mof', 'wmiprvse', 'persistencia', 'persistence', 'get-ciminstance', 'remove-ciminstance', 'interval', 'evasion'],
