    english_customer_response_template: 'Hi {{USERNAME}}, we detected an attempt to gain administrator privileges on one of your systems and to reset passwords of other accounts. We blocked the involved account, isolated the machine, and reversed the changes. Your own credentials were not compromised. We are hardening the system so this path is closed. No action is needed from you, but report any password change you did not request.',
