    english_customer_response_template: 'Hi {{USERNAME}}, we detected active ransomware on your computer and we isolated it immediately to stop the encryption from spreading. Your files on the affected machine are being restored from our verified backups; no ransom will be paid. Please do not turn off or restart the computer, and tell us immediately everything you opened or clicked before the alert. We will keep you updated on the restoration progress.',
