    business_impact: 'El infostealer entrega sesiones activas y contraseñas al atacante sin necesidad de romper nada: las cuentas del usuario quedan comprometidas aunque la contraseña no cambie (robo de cookies); el componente gusano amplía la infección a otros endpoints y convierte un caso puntual en un incidente de flota.',
