    english_customer_response_template: 'Hi {{USERNAME}}, we found an information-stealing program on your computer that exports saved passwords and browser sessions. We isolated the machine, removed the malware, and reset your password and multi-factor registration, because stolen sessions can bypass passwords. Please check your accounts for anything unfamiliar and never save corporate passwords in the browser on that machine again.',
    english_technical_explanation: 'Infostealer with worm propagation on {{HOSTNAME}} at {{TIMESTAMP}}: Get-MpThreat confirmed execution (DidThreatExecute true); DeviceProcessEvents showed access to browser credential stores (Login Data, Local State, cookies) consistent with T1003 credential theft, plus type 3 logon spread to additional hosts. Containment: host isolated, user sessions revoked with Revoke-MgUserSession, password reset and MFA re-registration (stolen cookies defeat password-only resets). Remediation: Remove-MpThreat plus full scans on all affected hosts; hash blocked fleet-wide. Verification: no executions of the sample and no anomalous sign-ins for 48 hours.',
