    english_customer_response_template: 'Hello team, the detection gap identified in the last hunting cycle has been closed: a new Sigma rule now detects suspicious scheduled task creation from user-writable paths. The rule is versioned in our repository, converted to Splunk syntax, and validated against 30 days of history with an acceptable false-positive rate. It will generate alerts from now on, mapped to MITRE T1053.005.',
