    escalation: 'Casos con requisito legal (datos personales, extorsión, fraude consumado) escalan al IR lead y al forense designado antes de remediación agresiva (RB-SOC-031); si la captura de memoria no es posible con las herramientas del estándar, documente la limitación y escale el caso con la nota.',
    english_customer_response_template: 'Hi {{USERNAME}}, to preserve the evidence of the security incident we kept your computer running but isolated, and captured its memory, network state, and logs before any cleaning. Your machine is now being remediated and returned to you shortly. Please do not attempt to reinstall or clean anything yourself, and tell us anything unusual you noticed before the alert.',
    english_technical_explanation: 'Evidence collection on {{HOSTNAME}} at {{TIMESTAMP}} following order of volatility: network containment without shutdown (New-NetFirewallRule outbound block), RAM image captured with the IR standard tool and hashed, live network state (Get-NetTCPConnection, arp, ipconfig), top processes with paths, and Security/System logs exported with wevtutil epl. All artifacts hashed (SHA256) and registered in the chain of custody before remediation started. Remotely collected by L1 under IR lead supervision; artifacts stored encrypted for forensic analysis.',
    keywords: ['orden de volatilidad', 'order of volatility', 'memoria', 'memory capture', 'winpmem', 'dumpit', 'forense', 'forensics', 'cadena de custodia', 'chain of custody', 'hash', 'evtx', 'wevtutil', 'conexiones', 'get-nettcpconnection', 'fileless', 'no reiniciar'],
