      'New-NetFirewallRule -DisplayName "SOC Gestion {{TICKET_ID}}" -Direction Outbound -Action Allow -RemoteAddress "10.0.0.0/8"',
      'Disable-NetFirewallRule -DisplayName "SOC Contencion {{TICKET_ID}}"',
      'Get-NetTCPConnection -State Established | Select-Object LocalAddress, LocalPort, RemoteAddress, RemotePort, OwningProcess',
      'Get-MpComputerStatus | Format-List AMServiceEnabled, RealTimeProtectionEnabled',
      'Get-MpThreat | Format-List ThreatName, SeverityID, DidThreatExecute, Resources',
