        expected: 'CSV con cada archivo descargado: fecha, IP de origen, sitio y nombre de archivo.',
        explanation: 'El CSV dimensiona el activo afectado (qué sitios, qué archivos) y es evidencia directa para el ticket y para la DPO.',
