        expected: 'Credencial nueva con cambio forzado; permisos de la cuenta sobre los sitios descargados revisados y recortados si exceden el rol.',
        explanation: 'Endurezca la política DLP: bloquear descargas desde dispositivos no administrados y umbral de alerta por volumen; las lecciones cierran en RB-SOC-040.',
