    escalation: 'Descarga con datos personales o volumen sobre el umbral de la política es P1: IR lead, CISO y legal/DPO por RB-SOC-031; si la sesión proviene de una IP o cliente ajeno al usuario, trate la cuenta como comprometida y siga RB-SOC-005 y RB-SOC-002; fuga interna confirmada pasa a RRHH y legal con la evidencia recolectada.',
    english_customer_response_template: 'Hi {{USERNAME}}, our data loss prevention system flagged an unusually large download of SharePoint and OneDrive files from your account. We signed out your active sessions and reset your password as a precaution while we validate the activity. If you performed this download as part of an authorized task, please reply to this ticket with the business justification and the approval record. If you did not perform it, do not attempt to sign in until we confirm your account is secure.',
    english_technical_explanation: 'Cloud exfiltration alert for {{USERNAME}} at {{TIMESTAMP}}: DLP policy matched mass FileDownloaded operations (T1213.002) in OfficeActivity, several hundred files in under an hour versus a baseline of dozens. SigninLogs correlation showed the download session originated from {{SOURCE_IP}}, inconsistent with the user history. Containment: Revoke-MgUserSignInSession plus forced password rotation and site permission review; unified audit log exported via Search-UnifiedAuditLog for scope (sites and file inventory). Verification: zero FileDownloaded events for the account after containment and no other accounts over threshold. Data classification and breach assessment handed to DPO and legal under RB-SOC-031.',
    keywords: ['exfiltracion', 'exfiltration', 'dlp', 'descarga masiva', 'mass download', 'sharepoint', 'onedrive', 'officeactivity', 'filedownloaded', 'purview', 'search-unifiedauditlog', 'fuga de datos', 'data leak', 't1213'],
