        expected: 'El dispositivo extraíble queda deshabilitado en el host: cero escrituras nuevas mientras se recupera físicamente.',
        explanation: 'La contención combina lo técnico (deshabilitar el medio y aplicar la política de device control que niega USBSTOR en la flota) con lo físico: recuperar el dispositivo con el manager y RRHH.',
