    english_customer_response_template: 'Hi {{USERNAME}}, our data loss prevention monitoring flagged a large copy of corporate files from your computer to a removable USB device. We disabled further writes to that device while we validate the activity. If this transfer was authorized, please reply with the approval record and the inventory of the device; if you did not perform it, stop using the computer and contact us immediately. Unauthorized transfers of corporate data have legal implications and are handled under our internal policy.',
    english_technical_explanation: 'USB exfiltration alert on {{HOSTNAME}} at {{TIMESTAMP}}: DLP policy matched mass file creation under USBSTOR paths in DeviceFileEvents (T1052 exfiltration over physical medium). Device mount anchored via SecurityEvent 6416 (PnP Activity) minutes before the copy window; initiating process explorer.exe with prior rar.exe staging identified in DeviceProcessEvents, indicating deliberate user action rather than malware. Scope documented with file inventory, hashes and device InstanceId. Containment: device disabled via Disable-PnpDevice, physical recovery coordinated with HR, device control policy blocking removable storage deployed fleet-wide. Verification: zero new USBSTOR writes after containment; case handed to legal for breach assessment under RB-SOC-031.',
