        action: 'Detección: extraer los payloads reales de los logs del WAF',
        command: 'CommonSecurityLog | where TimeGenerated > ago(24h) | where isnotempty(RequestUrl) | where RequestUrl has_any ("union select", "sleep(", "information_schema", " or 1=1") | project TimeGenerated, SourceIP, RequestMethod, RequestUrl | order by TimeGenerated asc',
        expected: 'Serie de peticiones con los payloads: IPs atacantes, endpoint afectado (/producto?id=...) y el vector exacto intentado.',
        explanation: 'Filtre también variantes codificadas (%27, comentarios /**/) y registre la técnica MITRE (T1190) en el ticket: el patrón completo alimenta el bloqueo y la regla.',
