        expected: 'Ranking de IPs atacantes: una o pocas concentran el intento; verbos y rutas revelan la automatización (escáner).',
        explanation: 'Compare contra las IP de los escáneres autorizados antes de bloquear: el falso positivo del escáner interno es frecuente (RB-SOC-032).',
