    business_impact: 'Un secreto en un repositorio público es cosechado por bots en minutos y termina vendido o usado para acceso automatizado (T1078 Valid Accounts): correos, APIs, nube y despliegues quedan expuestos mientras el secreto siga válido; rotar temprano cuesta una fracción del incidente que causa su uso.',
