        expected: 'Credencial de la cuenta de servicio rotada; el secreto de aplicación queda inválido tras Remove-MgApplicationPassword.',
        explanation: 'Regla de oro: un secreto visto en público se considera comprometido aunque nadie lo haya usado; rote también el secreto de la aplicación (Remove-MgApplicationPassword -ApplicationId "<app-id>" -KeyId "<key-id>"), revoque el PAT y las sesiones (Revoke-MgUserSignInSession), y solo entonces limpie el histórico.',
