    english_customer_response_template: 'Hello {{USERNAME}}, our secret scanning program detected that a configuration file with service credentials was pushed to a public repository. We rotated all exposed credentials before any misuse was observed, invalidated the sessions associated with them, and cleaned the repository history. Please review the secure storage guidance linked in this ticket: credentials must live in the approved vault, never in code. We will keep monitoring the affected accounts for the next 30 days.',
    english_technical_explanation: 'Exposed credentials in a public repository (T1552.001) detected at {{TIMESTAMP}} via secret scanning alerts for nexora-sa/api-facturacion: service account password and Entra application secret embedded in config/produccion.env. Exposure window dated with git log -S (pickaxe) from the introducing commit to rotation. Usage hunt: SigninLogs and AADNonInteractiveUserSignInLogs for svc-facturacion plus AzureActivity by Caller showed authentications only from corporate CI/CD ranges; no attacker usage confirmed. Containment per rotate-first doctrine: Update-MgUser password rotation, Remove-MgApplicationPassword for the app secret, Revoke-MgUserSignInSession, PAT revoked in the platform. Remediation: history rewritten with git filter-repo --replace-text, push protection and organization-wide secret scanning enabled, secrets moved to Key Vault. Verification: scanning alerts resolved and authentications only from expected sources.',
