    business_impact: 'Sin postmortem, el mismo incidente vuelve a ocurrir con el mismo costo: el informe ejecutivo además habilita decisiones de inversión en seguridad y es insumo del regulador o del seguro cuando hubo notificación; un postmortem bien hecho baja el MTTD y el MTTR del siguiente incidente (RB-SOC-030).',
