        expected: 'CSV de métricas del caso: distribución de alertas por detección y severidad, base del informe.',
        explanation: 'El ejecutivo va en una página: qué pasó, impacto, causa raíz, acciones con fecha y pedido de inversión; el RCA técnico detallado va de anexo con timeline, matriz MITRE y comandos de respuesta.',
